\begin{fact}\label{decomposition to hyperbolic pairs}
    Every $V$ of dimension $2n$ as above has a decomposition $V=Span \{e_1,f_1, \ldots ,e_n,f_n \} $ where:

    \begin{enumerate}
        \item $e_i,f_i$ form an hyperbolic pair.

        \item $Span \{e_i,f_i\}$ is orthogonal to $Span \{ e_j,f_j \}_{j\neq i}$.
    \end{enumerate}
\end{fact}
